import{_ as i,a0 as u,w as d,s as m,I as e,x as n,a1 as t,A as p,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在终端下以后台模式运行Linux程序 | LCTT x X-CMD","titleTemplate":false,"description":"如何在终端下以后台模式运行Linux程序 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在终端下以后台模式运行Linux程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在终端下以后台模式运行Linux程序 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141204 How To Run Linux Programs From The Terminal In Background Mode","title":"如何在终端下以后台模式运行Linux程序","tag":"201501","desc":""},"relativePath":"201501/20141204 How To Run Linux Programs From The Terminal In Background Mode.md","filePath":"[post].md"}'),l={name:"201501/20141204 How To Run Linux Programs From The Terminal In Background Mode.md"};function s(f,o,T,x,L,g){const r=u("Link");return d(),m("div",null,[o[16]||(o[16]=e("h1",{id:"如何在终端下以后台模式运行linux程序",tabindex:"-1"},[n("如何在终端下以后台模式运行Linux程序 "),e("a",{class:"header-anchor",href:"#如何在终端下以后台模式运行linux程序","aria-label":"Permalink to “如何在终端下以后台模式运行Linux程序”"},"​")],-1)),o[17]||(o[17]=e("p",null,[e("img",{src:"http://0.tqn.com/y/linux/1/W/r/G/1/terminal.JPG",alt:"Linux Terminal Window."})],-1)),o[18]||(o[18]=e("p",null,[e("em",null,"Linux终端窗口")],-1)),o[19]||(o[19]=e("p",null,"这是一个简短但是非常有用的教程：它向你展示从终端运行Linux应用程序的同时，如何保证终端仍然可以操作。",-1)),o[20]||(o[20]=e("p",null,"在Linux中有许多方式可以打开一个终端，这主要取决于你的发行版的选择和桌面环境。",-1)),e("p",null,[o[1]||(o[1]=n("使用Ubuntu的话，你可以使用CTRL + ALT + T组合键打开一个终端。你也可以点击超级键(Windows键)打开一个终端窗口。在键盘上，",-1)),t(r,{href:"http://linux.about.com/od/howtos/fl/Learn-Ubuntu-The-Unity-Dash.htm"},{default:p(()=>[...o[0]||(o[0]=[n("打开Ubuntu Dash",-1)])]),_:1}),o[2]||(o[2]=n('，然后搜索"TERM"。点击"Term"图标将会打开一个终端窗口。',-1))]),o[21]||(o[21]=a(`<p>其他诸如XFCE, KDE, LXDE, Cinnamon和MATE的桌面环境，你将会在菜单中发现“终端”这个应用。还有一些发行版会把终端图标放在菜单项，或者在面板上放置终端启动器。</p><p>你可以在终端里面输入一个程序的名字来启动一个应用。举例，你可以通过输入&quot;firefox&quot;启动火狐浏览器。</p><p>从终端运行程序的好处是可以使用额外的选项。</p><p>举个例子，如果你输入下面的命令，一个新的火狐浏览器将会打开，而且默认的搜索引擎将会搜索引号之间的词语：</p><pre><code>firefox -search &quot;Linux.About.Com&quot;
</code></pre><p>你会发现，如果你运行火狐浏览器，应用程序打开后，控制权将会回到终端（重新出现了命令提示符），这将意味着你可以继续在终端工作。</p><p>通常情况下，如果你通过终端运行一个程序，程序打开后，并且直到那个程序关闭结束，你都将不会获得终端的控制权。这是因为你是在前台打开程序的。</p><p>想要从终端运行一个程序，并且立即将终端的控制权返回给你，你需要以后台进程的方式打开程序。</p><p>为了以后台进程的方式打开一个程序，只需要添加符号(&amp;)到命令中，如下面所示：</p><pre><code>libreoffice &amp;
</code></pre><p>在终端中仅仅提供程序的名字，应用程序可能运行不了。如果程序不存在于一个设置在PATH 环境变量的文件夹中，你需要指定完整的路径名来运行程序。</p><pre><code>/path/to/yourprogram &amp;
</code></pre><p>如果你并不确定一个程序是否存在于Linux文件系统中，使用find或者locate命令来查找该应用程序。</p><p>找一个文件的语法如下：</p><pre><code>find /path/to/start/from -name programname
</code></pre><p>举个例子，可以使用下面的命令寻找Firefox的位置：</p><pre><code>find / -name firefox
</code></pre><p>输出会很快滚动出很多，所以你可以以管道的方式控制输出的多少：</p><pre><code>find / -name firefox | more

find / -name firefox | less
</code></pre><p>find命令将会返回因权限拒绝而发生错误的文件夹数量，这些文件夹你没有权限去搜索。</p><p>你可以使用sudo命令提升你的权限。如果sudo没有安装，你需要切换到拥有权限的用户：</p><pre><code>sudo find / -name firefox | more
</code></pre><p>如果你知道你想寻找的文件在你的当前文件夹中，你可以一个点代替先前的斜线，如下：</p><pre><code>sudo find . -name firefox | more
</code></pre><p>你可能不需要sudo来提升权限。如果你在home文件夹中寻找文件，sudo就不需要。</p><p>一些应用程序需要提升用户权限来运行，你可能得到一个缺少权限的错误，除非你使用一个具有足够权限的用户，或者使用sudo提升你的权限。</p><p>下面是一个小花招。如果你运行一个程序，而且它需要提升权限来运行，输入下面命令来提升权限重新执行：</p><pre><code>sudo !!
</code></pre><hr>`,29)),e("p",null,[o[4]||(o[4]=n("via: ",-1)),t(r,{href:"http://linux.about.com/od/commands/fl/How-To-Run-Linux-Programs-From-The-Terminal-In-Background-Mode.htm"},{default:p(()=>[...o[3]||(o[3]=[n("http://linux.about.com/od/commands/fl/How-To-Run-Linux-Programs-From-The-Terminal-In-Background-Mode.htm",-1)])]),_:1})]),e("p",null,[o[8]||(o[8]=n("作者：",-1)),t(r,{href:"http://linux.about.com/bio/Gary-Newell-132058.htm"},{default:p(()=>[...o[5]||(o[5]=[n("Gary Newell",-1)])]),_:1}),o[9]||(o[9]=n(" 译者：",-1)),t(r,{href:"https://github.com/su-kaiyao"},{default:p(()=>[...o[6]||(o[6]=[n("su-kaiyao",-1)])]),_:1}),o[10]||(o[10]=n(" 校对：",-1)),t(r,{href:"https://github.com/wxy"},{default:p(()=>[...o[7]||(o[7]=[n("wxy",-1)])]),_:1})]),e("p",null,[o[13]||(o[13]=n("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...o[11]||(o[11]=[n("LCTT",-1)])]),_:1}),o[14]||(o[14]=n(" 原创翻译，",-1)),t(r,{href:"http://linux.cn/"},{default:p(()=>[...o[12]||(o[12]=[n("Linux中> 国",-1)])]),_:1}),o[15]||(o[15]=n(" 荣誉推出",-1))])])}const P=i(l,[["render",s]]);export{w as __pageData,P as default};
